20	import java.nio.charset.StandardCharsets;
21	import java.security.MessageDigest;
22	import java.security.NoSuchAlgorithmException;
23	import java.util.Locale;
24	
25	import org.springframework.samples.petclinic.model.Owner;
26	
27	/**
28	 * Utility for deriving an owner's {@code identityKey}, the single value into which all
29	 * duplicate detection is consolidated. The key is the lower-case hexadecimal SHA-256 digest of
30	 * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}: the owner's telephone
31	 * in {@link TelephoneNormalizer E.164} form, the lower-cased e-mail address (or an empty string
32	 * when absent), and the {@link Soundex Soundex} code of the last name.
33	 *
34	 * <p>Because the telephone is part of the key, two owners with the same last name and postcode but
35	 * different telephones have different identity keys; only an exact whole-key match between a new
36	 * owner and an existing one is a hard duplicate. Owners that merely share the last name's Soundex
37	 * code and postcode are surfaced as a soft match instead.
38	 */
39	public final class IdentityKeyNormalizer {
40	
41	    private IdentityKeyNormalizer() {
42	    }
43	
44	    /**
45	     * Derive the owner's identity key.
46	     *
47	     * @param owner the owner (may be {@code null})
48	     * @return the derived identity key, or {@code null} when the owner is {@code null}
49	     */
50	    public static String derive(Owner owner) {
51	        if (owner == null) {
52	            return null;
53	        }
54	        String telephone = TelephoneNormalizer.toComparable(owner.getTelephone());
55	        String email = owner.getEmail() == null ? "" : owner.getEmail().toLowerCase(Locale.ROOT);
56	        String soundex = Soundex.encode(owner.getLastName());
57	        return sha256Hex(telephone + "|" + email + "|" + soundex);
58	    }
59	
60	    /**
61	     * Returns the full lower-case hexadecimal SHA-256 digest of the UTF-8 bytes of {@code value}.
62	     */
63	    private static String sha256Hex(String value) {
64	        try {
65	            byte[] digest = MessageDigest.getInstance("SHA-256")
66	                .digest(value.getBytes(StandardCharsets.UTF_8));
67	            StringBuilder sb = new StringBuilder(digest.length * 2);
68	            for (byte b : digest) {
69	                sb.append(String.format("%02x", b));
70	            }
71	            return sb.toString();
72	        }
73	        catch (NoSuchAlgorithmException e) {
74	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
75	        }
76	    }
77	}
