95	package org.springframework.samples.petclinic.rest.validation;
96	
97	/**
98	 * Utility computing the standard American Soundex code of a name: the retained (upper-cased)
99	 * first letter followed by up to three digits derived from the remaining consonants, zero-padded
100	 * to a four-character code. Two names that sound alike therefore share a code, which is how the
101	 * owner {@code identityKey} and the soft-duplicate rule group owners by last name.
102	 *
103	 * <p>Non-letters are ignored, vowels (and {@code y}) separate otherwise-adjacent equal codes, and
104	 * {@code h}/{@code w} are transparent (they do not separate). A {@code null} or letter-free value
105	 * encodes to an empty string.
106	 */
107	public final class Soundex {
108	
109	    private Soundex() {
110	    }
111	
112	    /**
113	     * Encode the supplied name as its four-character Soundex code.
114	     *
115	     * @param name the raw name (may be {@code null})
116	     * @return the Soundex code, or an empty string when {@code name} is {@code null} or has no letters
117	     */
118	    public static String encode(String name) {
119	        if (name == null) {
120	            return "";
121	        }
122	        StringBuilder letters = new StringBuilder();
123	        for (int i = 0; i < name.length(); i++) {
124	            char c = name.charAt(i);
125	            if (Character.isLetter(c)) {
126	                letters.append(Character.toUpperCase(c));
127	            }
128	        }
129	        if (letters.length() == 0) {
130	            return "";
131	        }
132	        char first = letters.charAt(0);
133	        StringBuilder code = new StringBuilder().append(first);
134	        char prev = codeOf(first);
135	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
136	            char c = letters.charAt(i);
137	            if (c == 'H' || c == 'W') {
138	                // Transparent: two same-coded letters split by H/W stay a single code.
139	                continue;
140	            }
141	            char digit = codeOf(c);
142	            if (digit != '0' && digit != prev) {
143	                code.append(digit);
144	            }
145	            // A vowel (or Y) resets the running code so a repeat after it is coded again.
146	            prev = isVowel(c) ? '0' : digit;
147	        }
148	        while (code.length() < 4) {
149	            code.append('0');
150	        }
151	        return code.substring(0, 4);
152	    }
153	
154	    private static boolean isVowel(char c) {
155	        return c == 'A' || c == 'E' || c == 'I' || c == 'O' || c == 'U' || c == 'Y';
156	    }
157	
158	    private static char codeOf(char c) {
159	        return switch (c) {
160	            case 'B', 'F', 'P', 'V' -> '1';
161	            case 'C', 'G', 'J', 'K', 'Q', 'S', 'X', 'Z' -> '2';
162	            case 'D', 'T' -> '3';
163	            case 'L' -> '4';
164	            case 'M', 'N' -> '5';
165	            case 'R' -> '6';
166	            default -> '0';
167	        };
168	    }
169	}
