192	/**
193	 * Immutable structured audit event emitted via the {@code AUDIT} logger whenever an owner is
194	 * created. Serialized with the application's Jackson {@code ObjectMapper} it yields the JSON object
195	 * {@code {seq, ownerId, memberId, membershipLevel, event:'OWNER_CREATED'}}; the key order is
196	 * pinned by {@link JsonPropertyOrder}.
197	 *
198	 * <p>{@code seq} is a monotonically increasing integer across creates, so the ordering of events
199	 * is recoverable from the log alone. The event carries the owner's <em>current primary
200	 * identifier</em>, the unified {@code memberId}, so downstream consumers always see the identifier
201	 * that currently identifies the owner.
202	 *
203	 * <p>The record is immutable; once emitted its fields never change.
204	 *
205	 * @param seq             monotonically increasing sequence number across creates
206	 * @param ownerId         the persisted owner's id
207	 * @param memberId        the owner's current primary identifier
208	 * @param membershipLevel the owner's capped numeric membership level (may be {@code null})
209	 */
210	@JsonPropertyOrder({"seq", "ownerId", "memberId", "membershipLevel", "event"})
211	record OwnerCreatedAuditEvent(long seq, Integer ownerId, String memberId, Integer membershipLevel) {
212	
213	    /** Discriminator value carried in the {@code event} field. */
214	    static final String EVENT = "OWNER_CREATED";
215	
216	    /** Constant discriminator serialized as the {@code event} property. */
217	    @JsonProperty("event")
218	    String event() {
219	        return EVENT;
220	    }
221	}
